from __future__ import annotations
import hashlib,json,sys,time
from pathlib import Path
import joblib,numpy as np,pandas as pd
from sklearn.ensemble import ExtraTreesClassifier
from sklearn.metrics import confusion_matrix,roc_auc_score
from sklearn.model_selection import GroupShuffleSplit
from sklearn.preprocessing import StandardScaler
HERE=Path(__file__).resolve(); ROOT=HERE.parents[1]; DATA=ROOT/'data'; REPORTS=ROOT/'reports'; sys.path.insert(0,str(HERE.parent)); from url_features import FULL_FEATURES,domain_group,extract_url_features
def met(y,p,t):
 y=np.asarray(y,dtype=int); z=np.asarray(p)>=t; tn,fp,fn,tp=confusion_matrix(y,z,labels=[0,1]).ravel(); return {'n':int(len(y)),'benign_fpr':float(fp/max(1,tn+fp)),'malicious_recall':float(tp/max(1,fn+tp)),'confusion_matrix':[[int(tn),int(fp)],[int(fn),int(tp)]],'roc_auc':float(roc_auc_score(y,p))}
def threshold(y,p):
 grid=np.linspace(.0005,.9995,1999); y=np.asarray(y); s=np.sort(p[y==0]); b=np.sort(p[y==1]); f=s.size-np.searchsorted(s,grid,'left'); r=b.size-np.searchsorted(b,grid,'left'); fr=f/max(1,s.size); rr=r/max(1,b.size); ok=np.flatnonzero(fr<=.01); ok=ok if len(ok) else np.arange(len(grid)); i=ok[np.lexsort((grid[ok],fr[ok],-rr[ok]))[0]]; return float(grid[i])
def main():
 d=pd.read_csv(DATA/'final_dataset.csv'); rem=pd.read_csv(DATA/'remediation_hard_negatives_v3.csv'); X=d[FULL_FEATURES].astype(np.float32); y=d.label.astype(int).to_numpy(); g=d.url.map(domain_group); tr,rest=next(GroupShuffleSplit(n_splits=1,test_size=.4,random_state=42).split(X,y,g)); vr,te=next(GroupShuffleSplit(n_splits=1,test_size=.5,random_state=42).split(X.iloc[rest],y[rest],g.iloc[rest])); vi,tei=rest[vr],rest[te]; sc=StandardScaler().fit(X.iloc[tr]); Xs=sc.transform(X); rx=sc.transform(pd.DataFrame([extract_url_features(u,FULL_FEATURES) for u in rem.url],columns=FULL_FEATURES)); ry=rem.label.astype(int).to_numpy(); hard=d.DatasetSource.to_numpy()=='hard'; fitX=np.vstack([Xs[tr],rx]); fity=np.concatenate([y[tr],ry]); sw=np.concatenate([np.ones(len(tr)),np.full(len(rem),5.)]); m=ExtraTreesClassifier(n_estimators=40,max_depth=18,min_samples_leaf=2,n_jobs=1,class_weight='balanced',random_state=42); start=time.perf_counter(); m.fit(fitX,fity,sample_weight=sw); pv=m.predict_proba(Xs[vi])[:,1]; t=threshold(y[vi],pv); pt=m.predict_proba(Xs[tei])[:,1]; ph=m.predict_proba(Xs[hard])[:,1]; name='challenger_hardsource_v3_extra40'; p=ROOT/'model'/'challengers'/name; p.mkdir(exist_ok=True); joblib.dump(m,p/'model.joblib'); joblib.dump(sc,p/'scaler.joblib'); r={'experiment_id':name,'architecture':'ExtraTreesClassifier','features':FULL_FEATURES,'seed':42,'threshold':t,'remediation_dataset_sha256':hashlib.sha256((DATA/'remediation_hard_negatives_v3.csv').read_bytes()).hexdigest(),'remediation_rows':len(rem),'remediation_weight':5.0,'fit_seconds':time.perf_counter()-start,'artifact':'model/challengers/'+name+'/model.joblib','validation':met(y[vi],pv,t),'test':met(y[tei],pt,t),'hard_source_holdout':met(y[hard],ph,t),'serialized_model_bytes':int((p/'model.joblib').stat().st_size)}; (p/'metadata.json').write_text(json.dumps(r,indent=2),encoding='utf-8'); stamp=pd.Timestamp.now(tz='UTC').isoformat(); (REPORTS/'URL_FINAL_REMEDIATION_EXPERIMENTS.json').write_text(json.dumps({'generated_at':stamp,'experiment':r,'previous_best':'challenger_hardsource_v2_extra40','frozen_champion_untouched':True},indent=2),encoding='utf-8'); (REPORTS/'URL_FINAL_REMEDIATION_EXPERIMENTS.md').write_text(f"# URL-ML Focused Final Remediation Experiments\n\nFresh finalist trained from scratch on remediation v3 (3,430 benign URLs across 49 source-diverse domains; 686 HTTP rows), targeting residual ordinary/deep non-HTTPS paths.\n\n- Threshold: {t:.4f} (dense validation-only selection)\n- Validation FPR/recall: {r['validation']['benign_fpr']:.4f}/{r['validation']['malicious_recall']:.4f}\n- TEST FPR/recall: {r['test']['benign_fpr']:.4f}/{r['test']['malicious_recall']:.4f}\n- Hard-source FPR/recall: {r['hard_source_holdout']['benign_fpr']:.4f}/{r['hard_source_holdout']['malicious_recall']:.4f}\n- Model size: {r['serialized_model_bytes']:,} bytes\n\nThe prior v2 finalist and frozen champion were preserved.\n",encoding='utf-8');
 with (REPORTS/'EXPERIMENT_REGISTRY.jsonl').open('a',encoding='utf-8') as f: f.write(json.dumps({'experiment_id':name,'timestamp':stamp,'dataset_version':r['remediation_dataset_sha256'],'decision':'challenger','architecture':r['architecture'],'features':r['features'],'seed':42,'threshold':t,'validation':r['validation'],'test':r['test'],'hard_source_holdout':r['hard_source_holdout'],'model_size_bytes':r['serialized_model_bytes']})+'\n')
 print(json.dumps(r,indent=2))
if __name__=='__main__': main()
